paragraph.math:
$$\begin{array}{l}
  {{f^{\prime}{(x)}} = \frac{(x\ln x){(0)} - {(1)}(\ln x + 1)}{\left\lbrack x(\ln x) \right\rbrack^{2}}} \\
  {\phantom{f^{\prime}{(x)}} = {- \frac{\ln x + 1}{\left\lbrack x(\ln x) \right\rbrack^{2}}}}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{2}^{\infty}{\frac{1}{x\ln x}\mathit{dx}}} = {\lim\limits_{b\rightarrow\infty}{\int_{2}^{b}{\frac{1}{x\ln x}\mathit{dx}}}}} \\
  {\phantom{\int_{2}^{\infty}{\frac{1}{x\ln x}\mathit{dx}}} = {\lim\limits_{b\rightarrow\infty}{\lbrack\ln(\ln x)\rbrack}_{2}^{b}}} \\
  {\phantom{\int_{2}^{\infty}{\frac{1}{x\ln x}\mathit{dx}}} = {\lim\limits_{b\rightarrow\infty}\lbrack\ln(\ln b) - \ln(\ln 2)\rbrack}} \\
  {\phantom{\int_{2}^{\infty}{\frac{1}{x\ln x}\mathit{dx}}} = \infty}
  \end{array}$$
